package dev.eugheist.ttmodern;
import net.minecraft.world.item.*;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.level.Level;
final class KamiResourcesAudit {
 private static void check(boolean ok,String label){if(!ok)throw new IllegalStateException("TT KAMI resources: "+label);}
 static void run(net.minecraft.server.MinecraftServer server){
  for(var kind:KamiResources.Kind.values()){var stack=new ItemStack(KamiResources.item(kind));check(stack.getMaxStackSize()==64&&stack.getRarity()==(kind.ordinal()<6?Rarity.EPIC:Rarity.COMMON)&&!stack.getItem().isFoil(stack),"original stack/rarity/no glint "+kind);var restored=ItemStack.parseOptional(server.registryAccess(),(net.minecraft.nbt.CompoundTag)stack.save(server.registryAccess()));check(ItemStack.isSameItemSameComponents(stack,restored),"native persistence "+kind);}
  var research=thaumcraft.api.research.ResearchCategories.getResearch("DIMENSION_SHARDS");check(research!=null&&research.displayColumn==7&&research.displayRow==8&&research.isAutoUnlock()&&research.isRound()&&research.isStub()&&research.isConcealed()&&research.parentsHidden==null,"original clue flags/no KAMI mastery gate");check(dev.eugheist.tc4modern.ResearchProgress.completed(new net.minecraft.nbt.CompoundTag()).contains("DIMENSION_SHARDS"),"actual fresh-player auto unlock");
  var end=server.getLevel(Level.END);var nether=server.getLevel(Level.NETHER);var over=server.overworld();var enderman=EntityType.ENDERMAN.create(end);var pig=EntityType.ZOMBIFIED_PIGLIN.create(nether);var player=net.neoforged.neoforge.common.util.FakePlayerFactory.getMinecraft(over);var source=over.damageSources().playerAttack(player);
  check(DimensionalShardDrops.drop(enderman,source,.03125).is(KamiResources.item(KamiResources.Kind.ENDER_SHARD))&&DimensionalShardDrops.drop(enderman,source,Math.nextUp(.03125)).isEmpty(),"inclusive exact End threshold1/32");check(DimensionalShardDrops.drop(pig,source,.0625).is(KamiResources.item(KamiResources.Kind.NETHER_SHARD))&&DimensionalShardDrops.drop(pig,source,Math.nextUp(.0625)).isEmpty(),"inclusive exact Nether threshold1/16");
  check(DimensionalShardDrops.drop(EntityType.ENDERMAN.create(over),source,0).isEmpty()&&DimensionalShardDrops.drop(EntityType.ZOMBIFIED_PIGLIN.create(over),source,0).isEmpty(),"same mobs outside original dimensions rejected");check(DimensionalShardDrops.drop(EntityType.PIGLIN.create(nether),source,0).isEmpty(),"ordinary piglin is not original zombie pigman");check(DimensionalShardDrops.drop(pig,over.damageSources().magic(),0).isEmpty(),"player attribution required");
  var arrow=EntityType.ARROW.create(over);arrow.setOwner(player);check(!DimensionalShardDrops.drop(enderman,over.damageSources().arrow(arrow,player),0).isEmpty(),"projectile owner player accepted");
  var drops=new java.util.ArrayList<net.minecraft.world.entity.item.ItemEntity>();var original=new net.minecraft.world.entity.item.ItemEntity(end,1,2,3,new ItemStack(Items.ENDER_PEARL));drops.add(original);enderman.setPos(4,200,6);DimensionalShardDrops.append(new net.neoforged.neoforge.event.entity.living.LivingDropsEvent(enderman,source,drops,false),0);check(drops.size()==2&&drops.getFirst()==original&&drops.getLast().getItem().getCount()==1&&drops.getLast().getX()==4&&drops.getLast().getY()==200&&drops.getLast().getZ()==6,"event preserves existing loot/adds one shard at victim");
  var recipe=server.getRecipeManager().byKey(net.minecraft.resources.ResourceLocation.fromNamespaceAndPath(ThaumicTinkererModern.ID,"ichorium_nuggets")).orElseThrow().value();var input=net.minecraft.world.item.crafting.CraftingInput.of(1,1,java.util.List.of(new ItemStack(KamiResources.item(KamiResources.Kind.ICHORIUM))));check(recipe instanceof net.minecraft.world.item.crafting.CraftingRecipe,"native shapeless recipe registered");var crafting=(net.minecraft.world.item.crafting.CraftingRecipe)recipe;check(crafting.matches(input,over)&&crafting.assemble(input,server.registryAccess()).is(KamiResources.item(KamiResources.Kind.NUGGET))&&crafting.assemble(input,server.registryAccess()).getCount()==9,"native ichorium to nine nuggets");
  System.out.println("TT KAMI RESOURCES AUDIT: ALL PASS (eight item identities/rarity/persistence,auto clue,exact drop thresholds/dimensions/player attribution,event loot conservation,native9nugget recipe)");
 }
}
